xpath.script:
(function () {
    function irgApplyOnlinePracticeFilter() {
        var courseSelect = document.getElementById('course_id');
        var typeSelect = document.getElementById('practice_center_type_id');
        if (!courseSelect || !typeSelect) { return; }
        var selected = courseSelect.options[courseSelect.selectedIndex];
        var isOnline = selected && selected.getAttribute('data-irg-online') === '1';
        Array.prototype.forEach.call(typeSelect.options, function (option) {
            if (!option.value) { return; }
            var allowed = option.getAttribute('data-irg-online-ok') === '1';
            if (isOnline && !allowed) {
                option.hidden = true;
            }
        });
        var current = typeSelect.options[typeSelect.selectedIndex];
        if (current && current.hidden) {
            var firstVisible;
            Array.prototype.forEach.call(typeSelect.options, function (option) {
                if (!firstVisible && option.value && !option.hidden) {
                    firstVisible = option;
                }
            });
            if (firstVisible) {
                typeSelect.value = firstVisible.value;
                typeSelect.dispatchEvent(new Event('change'));
            }
        }
    }
    function irgScheduleOnlinePracticeFilter() {
        window.setTimeout(irgApplyOnlinePracticeFilter, 0);
    }
    var courseSelect = document.getElementById('course_id');
    if (courseSelect) {
        courseSelect.addEventListener('change', irgScheduleOnlinePracticeFilter);
    }
    window.addEventListener('load', irgScheduleOnlinePracticeFilter);
})();
